-- Проверка всех исторических отношений well—field и исходных формул ключей.
WITH expected AS (SELECT DISTINCT lower(to_hex(md5(to_utf8('well_field:' || entity_id || ':' || json_extract_scalar(payload,'$.field_id'))))) AS link_hk,lower(to_hex(md5(to_utf8('well:' || entity_id)))) AS well_hk,lower(to_hex(md5(to_utf8('field:' || json_extract_scalar(payload,'$.field_id'))))) AS field_hk FROM {{target:oil_dds__event}} WHERE event_type='well'), actual AS (SELECT link_hk,well_hk,field_hk FROM {{target:oil_dds__link_well_field}}) SELECT count(*) AS n FROM ((SELECT * FROM expected EXCEPT ALL SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT ALL SELECT * FROM expected)) q;
